import { Data } from '@514labs/moose-lib';

export interface UserActivity extends Data {
    eventId: string;
    eventTs: Date;
    userId: string;
    action: string;
    durationMs?: number;  // nullable field, will default to 0 in views
}

import { IngestPipeline } from "@514labs/moose-lib";
import { UserActivity } from "./ingest/UserActivity";

// User Activity ingestion pipeline
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
    table: { orderByFields: ["userId", "eventTs"] },
    stream: true,
    ingestApi: true,
});

