input.command:
./duckdb analytics.db << 'EOF'
-- Create user activity table
CREATE TABLE user_activity (
    event_id VARCHAR,
    event_ts TIMESTAMP,
    user_id VARCHAR,
    action VARCHAR,
    duration_ms INTEGER DEFAULT 0
);

-- Load sample data from CSV
COPY user_activity FROM '/data/samples/user_activity_sample.csv' 
  (AUTO_DETECT TRUE, HEADER TRUE, NULLSTR '', IGNORE_ERRORS TRUE);

-- Handle null duration_ms values
UPDATE user_activity SET duration_ms = 0 WHERE duration_ms IS NULL;

-- Check data loaded
SELECT COUNT(*) as total_records FROM user_activity;
SELECT * FROM user_activity LIMIT 5;
EOF

./duckdb analytics.db << 'EOF'
-- Query 1: Daily Summary per User
SELECT 'DAILY USER SUMMARY' as section;
SELECT * FROM daily_user_summary;

-- Query 2: Top Users Leaderboard  
SELECT 'TOP USERS LEADERBOARD' as section;
SELECT * FROM top_users_leaderboard;

-- Additional insights
SELECT 'SUMMARY STATISTICS' as section;
SELECT 
    COUNT(DISTINCT user_id) as total_users,
    COUNT(*) as total_events,
    SUM(duration_ms) as total_duration_ms,
    ROUND(AVG(duration_ms), 2) as overall_avg_duration
FROM user_activity;
EOF

./duckdb analytics.db << 'EOF'
-- Add new sample data to simulate real-time updates
INSERT INTO user_activity VALUES
    ('evt_011', '2026-01-17 09:00:00', 'usr_01', 'click', 180),
    ('evt_012', '2026-01-17 09:15:00', 'usr_04', 'view', 250),
    ('evt_013', '2026-01-17 10:00:00', 'usr_04', 'scroll', 320);

-- Show updated views
SELECT 'UPDATED DAILY SUMMARY' as section;
SELECT * FROM daily_user_summary WHERE activity_date = '2026-01-17';

SELECT 'UPDATED TOP USERS LEADERBOARD' as section;
SELECT * FROM top_users_leaderboard;

-- Show the complete setup summary
SELECT 'SETUP COMPLETE' as status;
SELECT 
    'Analytics database with 2 materialized views created' as summary,
    COUNT(*) as total_records,
    COUNT(DISTINCT user_id) as unique_users,
    MIN(event_ts) as earliest_event,
    MAX(event_ts) as latest_event
FROM user_activity;
EOF
